            <button class="btn btn-primary" type="submit">Send me the kit</button>
            <div id="lead-hint" class="hint">We’ll send 7 emails and one gentle check‑in. Unsubscribe anytime.</div>
            <div id="lead-error" class="error" role="alert">Please enter a valid email so we can deliver your kit.</div>
            <div class="success" role="status">Check your inbox — The Calm Kit is on the way.</div>
          </form>
        </div>
      </div>
    </section>

    <section class="cta" aria-label="Book coaching">
      <div class="container">
        <div class="box">
          <div>
            <div class="eyebrow">Begin today</div>
            <h3>Ready to create space for the you that isn’t rushed?</h3>
            <p class="small">A 20‑minute fit call helps us map the lightest next step for you — no pressure, no prep.</p>
          </div>
          <div>
            <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>
      </div>
    </section>
  </main>

  <footer>
    <div class="container f-grid">
      <div>
        <div class="f-brand">
          <span class="brand-badge" aria-hidden="true"></span>
          <div>
            <strong>{{BUSINESS_NAME}}</strong>
            <div class="small">{{TAGLINE}}</div>
          </div>
        </div>
        <p class="small" style="margin-top:10px;">This site shares educational information only and is not medical advice. If you’re under clinical care, coordinate changes with your provider.</p>
      </div>
      <div>
        <strong>Visit</strong>
        <div class="small" style="margin-top:8px;">{{ADDRESS}}<br />{{CITY}}, {{STATE}} {{ZIP}}</div>
        <div class="small" style="margin-top:8px;">Hours: {{HOURS}}</div>
      </div>
      <div>
        <strong>Contact</strong>
        <div class="small" style="margin-top:8px;">Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
        <div class="small" style="margin-top:6px;">Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
        <div class="small" style="margin-top:12px;"><a href="book.html">Book a consult</a></div>
      </div>
    </div>
  </footer>

  <script>
    (function(){
      const header = document.getElementById('site-header');
      const toggle = header.querySelector('.nav-toggle');
      const menu = document.getElementById('primary-menu');
      toggle.addEventListener('click', () => {
        const open = header.classList.toggle('open');
        toggle.setAttribute('aria-expanded', String(open));
      });
      menu.addEventListener('click', (e) => {
        if(e.target.tagName === 'A' && header.classList.contains('open')){
          header.classList.remove('open');
          toggle.setAttribute('aria-expanded', 'false');
        }
      });

      // Smooth scroll for on-page anchors
      document.querySelectorAll('a[href^="#"]').forEach(a => {
        a.addEventListener('click', (e) => {
          const id = a.getAttribute('href');
          if(id && id.length > 1){
            const el = document.querySelector(id);
            if(el){ e.preventDefault(); el.scrollIntoView({ behavior: (matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth'), block: 'start' }); }
          }
        });
      });

      // FAQ accordion
      document.querySelectorAll('.faq-item').forEach(item => {
        const btn = item.querySelector('button');
        const panel = item.querySelector('.faq-panel');
        btn.addEventListener('click', () => {
          const expanded = btn.getAttribute('aria-expanded') === 'true';
          document.querySelectorAll('.faq-item').forEach(i => {
            i.setAttribute('aria-expanded','false');
            const b = i.querySelector('button');
            const p = i.querySelector('.faq-panel');
            b.setAttribute('aria-expanded','false');
            p.style.maxHeight = null;
          });
          if(!expanded){
            item.setAttribute('aria-expanded','true');
            btn.setAttribute('aria-expanded','true');
            panel.style.maxHeight = panel.scrollHeight + 'px';
          }
        });
      });

      // Newsletter form validation
      document.querySelectorAll('form.validate').forEach(form => {
        const email = form.querySelector('input[type="email"]');
        const err = form.querySelector('.error');
        const ok = form.querySelector('.success');
        const showError = (msg) => { if(msg) err.textContent = msg; err.style.display = 'block'; ok.style.display = 'none'; };
        const showSuccess = () => { err.style.display = 'none'; ok.style.display = 'block'; };
        email.addEventListener('input', () => { if(email.validity.valid){ err.style.display = 'none'; } });
        form.addEventListener('submit', (e) => {
          e.preventDefault();
          if(!email.value || !email.validity.valid){
            showError('Please enter a valid email so we can deliver your kit.');
            email.focus();
            return;
          }
          showSuccess();
          form.reset();
        });
      });
    })();
  </script>
</body>
</html>"}
