  <script>
    (function(){
      const header = document.getElementById('site-header');
      const toggle = header.querySelector('.nav-toggle');
      const menu = document.getElementById('primary-menu');
      toggle.addEventListener('click', () => {
        const open = header.classList.toggle('open');
        toggle.setAttribute('aria-expanded', String(open));
      });
      menu.addEventListener('click', (e) => {
        if(e.target.tagName === 'A' && header.classList.contains('open')){
          header.classList.remove('open');
          toggle.setAttribute('aria-expanded', 'false');
        }
      });

      // Smooth scroll for on-page anchors
      document.querySelectorAll('a[href^="#"]').forEach(a => {
        a.addEventListener('click', (e) => {
          const id = a.getAttribute('href');
          if(id && id.length > 1){
            const el = document.querySelector(id);
            if(el){ e.preventDefault(); el.scrollIntoView({ behavior: (matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth'), block: 'start' }); }
          }
        });
      });

      // FAQ accordion
      document.querySelectorAll('.faq-item').forEach(item => {
        const btn = item.querySelector('button');
        const panel = item.querySelector('.faq-panel');
        btn.addEventListener('click', () => {
          const expanded = btn.getAttribute('aria-expanded') === 'true';
          document.querySelectorAll('.faq-item').forEach(i => {
            i.setAttribute('aria-expanded','false');
            const b = i.querySelector('button');
            const p = i.querySelector('.faq-panel');
            b.setAttribute('aria-expanded','false');
            p.style.maxHeight = null;
          });
          if(!expanded){
            item.setAttribute('aria-expanded','true');
            btn.setAttribute('aria-expanded','true');
            panel.style.maxHeight = panel.scrollHeight + 'px';
          }
        });
      });
    })();
  </script>
